/* PowerPoint-style editor: ribbon, task panes, dialogs, insert, show */
const TABS=['File','Home','Insert','Design','Transitions','Animations','Slide Show','Review','View','Help'];let curTab='Home';
const g=(l,h)=>`<div class="grp"><div class="gb">${h}</div><div class="gl">${l}</div></div>`;
const big=(ic,t,f,st,cls)=>`<button class="big ${cls||''}" ${st?`data-st="${st}"`:''} onclick="${f}"><i>${ic}</i>${t}</button>`;
