const mb=(t,f,ic)=>`<button class="mbtn" onclick="${f}(this)">${ic?`<span>${ic}</span> `:''}${t} &#9662;</button>`;
const bigm=(ic,t,f)=>`<button class="big mbtn" onclick="${f}(this)"><i>${ic}</i>${t} &#9662;</button>`;
const cbtn=(ic,key,def,title)=>`<span class="cbw"><button class="mbtn" title="${title}" onclick="colorMenu(this,'${key}')"><b style="border-bottom:4px solid ${def};padding:0 3px;font-size:14px" data-ck="${key}">${ic}</b>&#9662;</button></span>`;
