function placeImg(src,target){const im=new Image();im.onload=()=>{const max=1600;let s=src;if(Math.max(im.width,im.height)>max){const k=max/Math.max(im.width,im.height);const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);try{s=c.toDataURL(/png/.test(src.slice(0,20))&&im.width*im.height<1e6?'image/png':'image/jpeg',.9)}catch(e){}}
 if(target&&target.type==='phpic'){const t=target;let w=t.w,h=w*im.height/im.width;if(h>t.h){h=t.h;w=h*im.width/im.height}Object.assign(t,{type:'image',src:s,x:t.x+(t.w-w)/2,y:t.y+(t.h-h)/2,w,h});commit();return}
 if(target&&target.type==='image'){target.src=s;commit();return}
 let w=Math.min(deck.w*.6,im.width),h=w*im.height/im.width;if(h>deck.h*.8){h=deck.h*.8;w=h*im.width/im.height}addItem({type:'image',x:(deck.w-w)/2,y:(deck.h-h)/2,w,h,src:s,keep:1})};im.src=src}
