function itLabel(i){const t=i.type==='text'||i.type==='shape'?(i.text||'').split('\n')[0].slice(0,28):'';return (i.name||({text:'Text',shape:(SH[i.shape]||[i.shape])[0],image:'Picture',table:'Table',chart:'Chart',phpic:'Picture placeholder'})[i.type]||i.type)+(t?': '+t:'')}
