/* table ops */
function cellsInSel(it){const a=it.tsel.a,b=it.tsel.b;const r=[];for(let i=Math.min(a.r,b.r);i<=Math.max(a.r,b.r);i++)for(let j=Math.min(a.c,b.c);j<=Math.max(a.c,b.c);j++)r.push({r:i,c:j});return r}
function tblOp(op,t){const it=t||one();if(!it||it.type!=='table')return;endEdit();const c=tcell||{r:0,c:0};const R=it.cells.length,C=it.cells[0].length;const blank=()=>({t:''});
 if(op==='rowBelow'||op==='rowAbove'){const at=c.r+(op==='rowBelow'?1:0);it.cells.splice(at,0,Array.from({length:C},blank));if(it.rh)it.rh.splice(at,0,30)}
 else if(op==='colRight'||op==='colLeft'){const at=c.c+(op==='colRight'?1:0);it.cells.forEach(r=>r.splice(at,0,blank()));const n=C+1;it.cw=Array(n).fill(1/n)}
 else if(op==='delRow'){if(R<2){delItem();return}it.cells.splice(c.r,1);if(it.rh)it.rh.splice(c.r,1);tcell={r:Math.min(c.r,R-2),c:c.c}}
 else if(op==='delCol'){if(C<2){delItem();return}it.cells.forEach(r=>r.splice(c.c,1));it.cw=Array(C-1).fill(1/(C-1));tcell={r:c.r,c:Math.min(c.c,C-2)}}
 else if(op==='merge'){const cl=it.tsel?cellsInSel(it):[c,{r:c.r,c:c.c+1}];const rs=cl.map(x=>x.r),cs=cl.map(x=>x.c);const r0=Math.min(...rs),r1=Math.max(...rs),c0=Math.min(...cs),c1=Math.max(...cs);if(c1>=C||r1>=R)return;let txt=[];for(let i=r0;i<=r1;i++)for(let j=c0;j<=c1;j++){const x=it.cells[i][j];if(x.t)txt.push(x.t);if(i!==r0||j!==c0){x.hm=1}}const m=it.cells[r0][c0];m.t=txt.join(' ');m.html=null;m.cs=c1-c0+1;m.rs=r1-r0+1;delete it.tsel}
 else if(op==='split'){const m=it.cells[c.r][c.c];for(let i=c.r;i<c.r+(m.rs||1);i++)for(let j=c.c;j<c.c+(m.cs||1);j++)delete it.cells[i][j].hm;delete m.cs;delete m.rs}
 else if(op==='distRows'){it.rh=Array(R).fill(it.h/R)}else if(op==='distCols'){it.cw=Array(C).fill(1/C)}
 commit()}
function tblProp(k,v){const it=one();if(it&&it.type==='table'){it[k]=v;commit(true)}}
function tblShade(c){const it=one();if(!it||it.type!=='table')return;(it.tsel?cellsInSel(it):[tcell||{r:0,c:0}]).forEach(p=>{if(c)it.cells[p.r][p.c].fill=c;else delete it.cells[p.r][p.c].fill});commit(true)}
function tblVA(v){const it=one();if(!it||it.type!=='table')return;(it.tsel?cellsInSel(it):[tcell||{r:0,c:0}]).forEach(p=>it.cells[p.r][p.c].va=v);commit(true)}
