let FN={i:0,k:0};function findNext(){const f=$('fF').value;if(!f)return;const cs=$('fC').checked;const q=cs?f:f.toLowerCase();const hits=[];deck.slides.forEach((s,si)=>s.items.forEach(i=>{const t=(i.text||'')+(i.cells?i.cells.map(r=>r.map(c=>c.t).join(' ')).join(' '):'');if((cs?t:t.toLowerCase()).includes(q))hits.push([si,i.id])}));if(!hits.length){$('fRes').textContent='Not found';return}FN.k=(FN.k+1)%hits.length;const h=hits[FN.k];closeG();goSlide(h[0]);sel=[h[1]];drawSel();toast((FN.k+1)+' of '+hits.length)}
